import pathlib,json,collections,csv,html,hashlib,gzip,shutil
R=pathlib.Path(__file__).resolve().parent
api=json.loads((R/'api_audit.json').read_text());hist=json.loads((R/'historical_audit.json').read_text());local=json.loads((R/'PAPER_AUDIT.json').read_text());oldmech=json.loads((R/'historical_mechanisms.json').read_text());fmt=json.loads((R/'api_format_findings.json').read_text());pairs=json.loads((R/'api_paired_coverage.json').read_text())
models=collections.defaultdict(collections.Counter);studies=collections.defaultdict(collections.Counter)
for r in api['outcomes']:models[r['model']][r['outcome']]+=r['n'];studies[r['study']][r['outcome']]+=r['n']
allc=sum(models.values(),collections.Counter());usable=allc['valid']+allc['recoverable_fenced_json']+allc['recoverable_status_mismatch']
assert sum(allc.values())==api['rows'];assert api['missing_rows']==api['unexpected_rows']==0
for x,y in zip(local['reused_ablations'],json.loads((R.parent/'paper_complete_20261021/REUSED_COVERAGE.json').read_text())['ablations']):assert x['sha256']==y['sha256']
def n(x):return f'{x:,}'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(str(h))+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def outcome_rows():
 for m,c in models.items():
  total=sum(c.values());good=c['valid']+c['recoverable_fenced_json']+c['recoverable_status_mismatch'];yield [m,n(total),n(good),f'{good/total:.2%}',n(c['recoverable_fenced_json']),n(c['content_blocked']),n(c['error_unspecified']),n(total-good-c['content_blocked']-c['error_unspecified'])]
body='''<h1>Paper data coverage audit</h1><p>23 October 2026 · Six local judges and six API aliases · No additional model calls.</p>'''
body+=f'<div class="lead">All {n(api["rows"])} expected records in the new API export are present. There are no missing rows, duplicate response keys, unknown prompt IDs or unexpected assignments. {n(usable)} responses ({usable/api["rows"]:.2%}) are usable after a narrow JSON-format repair; {n(api["rows"]-usable)} remain unavailable for strict scoring.</div>'
body+='<p>“Present” includes failure records. “Usable” means the answer satisfies the study’s output/finish contract, including the explicitly documented Markdown-fence repair. It does not mean the answer is correct. A content block is never counted as a negative class.</p>'
body+='<h2>New API export: results by judge</h2>'+table(['API alias','Expected / present','Usable','Usable %','JSON recovered','Explicit blocks','Unspecified errors','Other unusable'],outcome_rows())
body+='<h2>What is missing in practice?</h2><ul>'
body+=f'<li><b>{n(allc["content_blocked"])} explicitly content-blocked answers.</b> These have content_filter/content_filtered finish reasons.</li>'
body+=f'<li><b>{n(allc["error_unspecified"])} error records with empty responses and no finish reason.</b> The CSV cannot establish whether these are content blocks, provider errors or other failures. Request-journal error summaries are needed to distinguish them.</li>'
body+=f'<li><b>{n(allc["truncated_unscorable"])} capped, unscorable outputs.</b> These are separate from seven probability-first traces whose first number remains scorable despite a capped explanation.</li>'
body+=f'<li><b>{n(allc["invalid_format"])} other format violations, {n(allc["ambiguous"])} ambiguous requests, {n(allc["empty_response"])} empty responses and {n(allc["possible_text_refusal"])} possible prose refusals.</b> Prose refusals are heuristic candidates, not provider-confirmed blocks.</li></ul>'
body+='<h2>Formatting recovery and protocol checks</h2><p><b>35,970 mechanism labels were recovered without model calls</b>: Sonnet 24,612; GPT-4o 9,493; Opus 5.5 1,865. Recovery only removes one complete enclosing Markdown JSON fence, then requires exact keys, allowed values, no duplicate keys and a normal finish. Original responses and statuses remain untouched; a separate recovered-label file is saved.</p>'
body+='<p><b>Opus 5.5 needs an inference-settings check.</b> Of its direct-output format violations, 16,798 contain an unsolicited explanation followed by a final integer: 5,837 main, 9,850 ablation and 1,111 2-NN. These remain excluded from the strict number-only analysis. This is more than a JSON wrapper issue. The CSV cannot confirm whether the cause is model noncompliance, a changed output cap, or a provider/wrapper difference. It also has 825 malformed/non-JSON mechanism outputs. Exact backend IDs and configuration manifests are needed for every API alias.</p>'
body+='<h2>Coverage by experiment and API judge</h2>'+table(['API alias','Study','Expected','Present','Usable','Unusable'],[[r['model'],r['study'],n(r.get('expected',0)),n(r.get('present',0)),n(r.get('usable',0)),n(r.get('present',0)-r.get('usable',0))] for r in api['coverage']])
body+='<p>The four original API judges intentionally have no new main-study requests: their existing 600,000 main records are reused. They are audited separately below.</p>'
body+='<h2>Earlier main-study API data</h2>'+table(['API alias','Present / 150,000','Usable','Unavailable'],[[r['model'],n(r['present']),n(r['outcomes'].get('usable',0)),n(r['present']-r['outcomes'].get('usable',0))] for r in hist['main']['models'] if r['model'] in models])
body+='<p>The earlier main table has no duplicate or unknown IDs. Its existing statuses are retained; this report does not infer reasons for those older invalid records.</p>'
body+='<h2>Local-judge coverage</h2>'
localrows=[['Main: control / saliency / 1-NN',900000,900000,0],['Seven ablation conditions',2100000,2100000,0],['2-NN',300000,300000,0],['Mechanism labels',150000,149759,241],['Probability first, rationale after',35919,35917,2],['Rationale first, probability after',35919,30922,4997]]
body+=table(['Study','Accounted','Usable','Unavailable'],[[s,n(a),n(v),n(b)] for s,a,v,b in localrows])
body+='<p>All final-addition rows were checked against canonical prompt membership and output hashes. The 350,000 reused ablation rows were scanned and their hashes matched the frozen reuse manifest. Earlier main and 2-NN records were independently scanned from saved local exports.</p><p>Local mechanism gaps: Mistral 237 invalid, Qwen27B 2 invalid, Qwen122B 2 truncated; Gemma, GLM and OLMo complete. Local probability-first has two preserved interrupted/ambiguous attempts; 516 capped explanations still have valid first probabilities. Reasoning-first has 4,997 capped outputs without a valid scored final answer, including 640 preserved earlier 256-token attempts in the overall study rather than a uniform 512-token rerun.</p>'
rr=next(r for r in hist['companions'] if 'first-512' in r['study']);body+=table(['Local judge','Reasoning-first usable','Capped / unscorable'],[[m,n(c.get('usable',0)),n(c.get('unscorable',0))] for m,c in rr['judges'].items()])
body+='<h2>Where API coverage is weakest</h2>'
ds=collections.defaultdict(collections.Counter)
with (R/'api_by_dataset_condition.csv').open() as f:
 for r in csv.DictReader(f):ds[r['dataset']][r['outcome']]+=int(r['count'])
dsrows=[]
for name,c in ds.items():
 total=sum(c.values());good=c['valid']+c['recoverable_fenced_json']+c['recoverable_status_mismatch'];dsrows.append([name,total,total-good,(total-good)/total,c['content_blocked'],c['error_unspecified']])
dsrows.sort(key=lambda r:-r[3]);body+=table(['Dataset','Records','Unavailable','Unavailable %','Explicit blocks','Unspecified errors'],[[a,n(b),n(c),f'{d:.2%}',n(e),n(f)] for a,b,c,d,e,f in dsrows])
body+='<p>These are descriptive record-level rates pooled across studies and judges, not estimates of task performance. WildJailbreak/WildGuard have many explicit blocks; ToxiGen and BeaverTails have many unspecified error records. Hallucination datasets also lose outputs through truncation and unsolicited explanations. Failures are therefore not confined to toxicity blockers.</p>'
body+='<h2>Matched comparison coverage</h2>'+table(['API alias','Study','Case groups','All conditions usable'],[[r['model'],r['study'],n(r['case_groups']),n(r['all_expected_conditions_usable'])] for r in pairs if r['study'] in ['main','ablation']])
body+='<p>Main rows require all three explanation conditions; ablation rows require all seven ablation conditions. These are within-study masks only. Final ablation-versus-full-NN comparisons must also intersect with that judge’s usable main NN response. The final performance analysis will compare the same cases within each contrast and report coverage, rather than treating refusals as class predictions or letting conditions use different denominators.</p>'
body+='<h2>Reasoning selections and provenance still needed</h2>'+table(['New API alias','Valid unchanged test pairs','Pairs unavailable for selection','Selected flips per order'],[[r['model'],n(r['unchanged']),n(r['excluded_unusable_main_pair']),n(r['selected_flips'])] for r in api['dynamic_selection']])
body+='<p>Every expected reasoning prompt is present, including 1,342 flips per order for Opus 5.5 and 1,255 for GPT-5.5. These selections exactly match the valid control/NN flips reconstructed from the CSV at 50. Dispatch uniqueness cannot be verified without the external journal. Request the small model/configuration manifest, validation summary and trace-selection receipts; an error-code summary from the journal would clarify the 70,889 unspecified errors. Input/output tokens and latency were omitted from the five-column file, so cost/latency results need a separate aggregate or sidecar export.</p>'
body+='<h2>Agreed paper structure</h2><ol><li><b>Theory / conceptual framework.</b> Explain labelled similarity and decision-relevant contrast and derive predictions about helpful and harmful outcomes. Treat these as testable mechanisms.</li><li><b>Performance experiments.</b> Main control/saliency/1-NN results at 50/50 and controlled validation tuning, precision–recall trade-offs and dataset-family results. Keep matched threshold pairs across explanation conditions for each tuning anchor.</li><li><b>Mechanism experiments.</b> Information ablations, random neighbour and 2-NN; annotator agreement and helpful/harmful/unchanged associations; probability-first versus reasoning-first as additional evidence. Expressed rationales are supporting evidence, not direct observations of internal computation.</li></ol><p>Selective NN gating is excluded from the main paper and can be omitted or placed in an appendix. Theoretical predictions and empirical results should be distinguished; avoid presenting correlational mechanism labels alone as proof of internal causality.</p>'
body+='<h2>Recommended next step</h2><p>Proceed with the complete local comparisons and matched API analyses. No blanket recollection is required. Resolve API settings/provenance and error categories before deciding whether specific records require repair or additional collection. Keep strict results and any later relaxed-output sensitivity analyses separate. No failed API request has been retried by this audit.</p>'
body+='<h2>Files</h2><ul>'+''.join(f'<li><a href="{x}">{x}</a></li>' for x in ['api_by_model_study.csv','api_outcomes.csv','api_by_dataset_condition.csv','api_response_issues.csv.gz','api_recovered_mechanism_labels.jsonl.gz','api_audit.json','PAPER_AUDIT.json','historical_audit.json'])+'</ul>'
style='body{font:16px/1.6 system-ui;max-width:1180px;margin:40px auto;padding:0 24px;color:#172334;background:#fafbfd}h1{font-size:32px}h2{margin-top:36px;font-size:23px}.lead{padding:20px;background:#eaf3ed;border-left:5px solid #278253;font-size:19px}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px;background:white}th,td{padding:9px 12px;border-bottom:1px solid #dce1e8;text-align:right}th:first-child,td:first-child{text-align:left}th{background:#edf1f6}a{color:#215c9b}p{max-width:1100px}'
(R/'report.html').write_text('<!doctype html><html><head><meta charset="utf-8"><title>Paper data coverage audit</title><style>'+style+'</style></head><body>'+body+'</body></html>')
summary=dict(api_rows=api['rows'],api_usable_after_fence_recovery=usable,api_unavailable=api['rows']-usable,api_recovered=allc['recoverable_fenced_json'],api_explicit_blocks=allc['content_blocked'],api_unspecified_errors=allc['error_unspecified'],api_absent=0,api_duplicates=0,local_studies=[dict(study=s,accounted=a,usable=v,unavailable=b) for s,a,v,b in localrows],paper_sections=['Theory','Performance experiments','Mechanism experiments'],selective_nn='Appendix only or omitted',reasoning_order='Mechanism evidence',source_sha256=api['source_sha256'])
(R/'SUMMARY.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
